var b="url",c="13__امضاء_قرارداد-چک_تضمین_نماینده_فروش_.html",d="generationDate",e=new Date(1756122260421.46),f="defaultAdaptiveView",g="name",h="",i="size",j="width",k=0,l="height",m="adaptiveViews",n="sketchKeys",o="s0",p="variables",q="OnLoadVariable",r="lg",s="vi",t="check",u="san",v="ba",w="loginv",x="inpa",y="page",z="packageId",A="3954f65c060840258112bde7c1cf57db",B="type",C="Axure:Page",D="13. امضاء قرارداد-چک تضمین(نماینده فروش)",E="notes",F="annotations",G="fn",H="1",I="ownerId",J="e0dbe35b1b40457cb32fd846687715fa",K="label",L="(Text Field)",M="Note",N="<p><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;\">کلیه فیلدهای دارای برچسب</span></p><p><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;\">&quot;</span><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;color:#D9001B;\">Fetch</span><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;\">&quot;</span></p><p><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;\">قرار گرفته در باکس صورتی از فرم ایجاد قرارداد که پیش از این توسط کاربر واحد توسعه بازار مورد تایید قرار گرفته است واکشی و در فرم قرارداد جهت ثبت و ارسال به نماینده فروش به منظور تایید و امضای نماینده درج گردد</span></p>",O="2",P="71a78130b56a4d708eb2eaa1f86eb26b",Q="خواهشمند است پس از د",R="<p><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;color:rgba(90, 21, 93, 0.847058823529412);\">مطابق استعلام دریافتی به صورت تلفنی در تاریخ 1404/05/15از جناب آقای عاشقان نژاد؛ امضای تمامی صاحبان امضا نماینده فروش با هویت شرکت/سازمان بر روی قرارداد اعطای نمایندگی فروش الزامی می باشد</span></p><p><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;color:#F60068;\">چنانچه شرکت یا سازمانی دارای چندین صاحب امضاء می باشد شرط رعایت </span><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;text-decoration:underline ;color:#0000FF;\">حدقل تعداد امضاء </span><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;color:#F60068;\">جهت اعتبار اسناد که در زمان ثبت شرکت تعیین گردیده است رعایت گردد</span></p><p><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;color:rgba(246, 0, 104, 0.847058823529412);\">****************************************************</span></p><p><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;color:rgba(17, 7, 30, 0.847058823529412);\">لازم به ذکر با بررسی های انجام شده مشخص گردید اطلاعات برخی از نمایندگان فروش با هویت شرکت/سازمان در سامانه فروش گیتی ناقص بوده و لازم است پیش از ایجاد قرارداد، اطلاعات ناقص هر نماینده فروش با هویت شرکت/سازمان تکمیل گردد</span></p>",S="3",T="d69739f042034e06b3c1fce98c843620",U="(Shape)",V="<p><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;\">در صورت درخواست چک از نماینده فروش از سوی گیتی کالا </span><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;color:#F20707;\">تایید و نهایی شدن قرارداد </span><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;\">پس از صدور چک و وارد نمودن مشخصات آن توسط نماینده فروش منوط به بررسی، تایید و نهایی سازی توسط شرکت گیتی کالا ایرانیان دارد</span></p>",W="4",X="98fb2ecec25d413e89fbfbec9d223e9e",Y="بازگشت",Z="<p><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;color:#FF0000;\">در صورت نیاز به پیوست قرارداد مندرج در بند 3-9 (تبصره 1)لازم است در هنگام تایید و امضاء قرارداد از سوی نماینده فروش، نماینده ملزم به بارگذاری مدارک ذکر شده در بند 3-9 (تبصره 1) باشد یا در پروفایل نماینده فروش، وی ملزم به بارگذاری مدارک ذکر شده باشد.در همین راستا به وی هم از طریق پنل نمایندگی و هم از طریق پیامک جهت بارگذاری مدارک فوق الذکر اطلاع رسانی گردد</span></p>",ba="5",bb="c4d3a7f6f12541479367adf29795004c",bc="تایید و امضاء",bd="<p><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;color:#D9001B;\">تایید و احراز هویت دو مرحله ای</span></p><p><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;\">به جهت افزایش امنیت قبل از ارسال کد احراز</span></p><p><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;\">&nbsp;هویت به تلفن همراه نماینده فروش جهت تایید و امضای قرارداد و پیش از آن از طریق یک پیامک مجزا به نماینده فروش با این محتوا ارسال گردد:</span></p><p><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;\"><br></span></p><p><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;\">&nbsp;</span><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;color:#0000BF;\">نماینده گرامی آقای علیرضا مختاری به کد ملی 1290496021شناسه نمایندگی 12345 شما در حال تایید و امضای الکترونیک قرارداد نمایندگی فروش به شماره 54321 می باشید در صورت اطمینان و موافقت با روش امضای الکترونیک کد ارسال شده را وارد سیستم نمایید</span></p><p><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;\">&nbsp;</span></p><p><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;\">پس از ورود کد در مرحله اول و اطمینان از اصالت آن جهت تایید و امضا مجددا به روش &quot;او پی تی&quot; جهت تایید و امضا قرارداد با استفاده از ارسال پیامک و تایید درستی آن نسبت به تایید و امضای </span></p><p><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;\">نهایی قرارداد اقدام گردد</span></p><p><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;\"><br></span></p><p><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;color:#D9001B;\">به عبارت دیگر در مرحله اول تایید نماینده بر روی روش امضای الکترونیک گرفته میشود و در مرحله دوم قرارداد تایید و امضا می گردد</span></p><p><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;color:#D9001B;\"><br></span></p><p><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;color:#000080;\">لازم به ذکر است چنانچه اضافه بر روش احراز هویت بر اساس کد ارسال شده به تلفن همراه نماینده فروش استفاده از روش </span><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;color:#D9001B;\">گواهی امضای دیجیتال</span><span style=\"font-family:'B Yekan', sans-serif;font-weight:400;color:#000080;\"> جهت امضای الکترونیک قرارداد امکان پذیر است این روش نیز پیاده سازی گردد</span></p>",be="style",bf="baseStyle",bg="627587b6038d43cca051c114ac41ad32",bh="pageAlignment",bi="center",bj="fill",bk="fillType",bl="solid",bm="color",bn=0xFFFFFFFF,bo="image",bp="imageAlignment",bq="near",br="imageRepeat",bs="auto",bt="favicon",bu="sketchFactor",bv="0",bw="colorStyle",bx="appliedColor",by="fontName",bz="Applied Font",bA="borderWidth",bB="borderVisibility",bC="borderFill",bD=0xFF797979,bE="cornerRadius",bF="cornerVisibility",bG="outerShadow",bH="on",bI=false,bJ="offsetX",bK=5,bL="offsetY",bM="blurRadius",bN="spread",bO="r",bP=0,bQ="g",bR="b",bS="a",bT=0.349019607843137,bU="adaptiveStyles",bV="interactionMap",bW="onLoad",bX="eventType",bY="OnPageLoad",bZ="description",ca="Page Loaded",cb="cases",cc="Case 1",cd="conditionString",ce="if value of loginv equals &quot;1&quot;",cf="isNewIfGroup",cg="caseColorHex",ch="AB68FF",ci="condition",cj="exprType",ck="binaryOp",cl="op",cm="==",cn="leftExpr",co="fcall",cp="functionName",cq="GetGlobalVariableValue",cr="arguments",cs="globalVariableLiteral",ct="variableName",cu="rightExpr",cv="stringLiteral",cw="value",cx="stos",cy="actions",cz="action",cA="setPanelState",cB="Set dyp13 to&nbsp; to State2 ",cC="displayName",cD="Set Panel State",cE="actionInfoDescriptions",cF="dyp13 to State2",cG="Set dyp13 to  to State2 ",cH="panelsToStates",cI="panelPath",cJ="e602b1e85b3540ab9395a69b498c7161",cK="stateInfo",cL="setStateType",cM="diagram",cN="stateNumber",cO=2,cP="stateValue",cQ="loop",cR="showWhenSet",cS="options",cT="compress",cU="Set ghar to&nbsp; to چک ",cV="ghar to چک",cW="Set ghar to  to چک ",cX="cf69f2074ba94fbca67abd11e3fb3d1d",cY=8,cZ="objects",da="id",db="dyp13",dc="friendlyType",dd="Dynamic Panel",de="dynamicPanel",df="styleType",dg="visible",dh=true,di=2288,dj=3920,dk="imageOverrides",dl="scrollbars",dm="none",dn="fitToContent",dp="propagate",dq="diagrams",dr="2e27b700d3bf4191ad4bbca38ba994e3",ds="State1",dt="Axure:PanelDiagram",du="f36c9c50d5b445439dc2505ea902ef15",dv="Group",dw="parentDynamicPanel",dx="panelIndex",dy="layer",dz="location",dA="x",dB=1288,dC="y",dD=9